  @override
  ConsumerState<WalletView> createState() => _WalletViewState();
}

class _WalletViewState extends ConsumerState<WalletView> {
  late final EventBus eventBus;
  late final String walletId;
  late final CryptoCurrency coin;

  late final bool isPivxShield;

  late WalletSyncStatus _currentSyncStatus;
  late NodeConnectionStatus _currentNodeStatus;

  late StreamSubscription<dynamic> _syncStatusSubscription;
  late StreamSubscription<dynamic> _nodeStatusSubscription;

  @override
  void initState() {
    walletId = widget.walletId;
    final wallet = ref.read(pWallets).getWallet(walletId);
    coin = wallet.info.coin;

    WidgetsBinding.instance.addPostFrameCallback((_) {
      ref.read(currentWalletIdProvider.notifier).state = wallet.walletId;
      // Wallets with a private balance open on public + private.
      ref.read(showTotalBalanceProvider.notifier).state = true;
    });

    if (!wallet.shouldAutoSync) {
      // enable auto sync if it wasn't enabled when loading wallet
      wallet.shouldAutoSync = true;
    }

    isPivxShield = wallet is PivxWallet && wallet.supportsShield;

    wallet.refresh();

    if (wallet.refreshMutex.isLocked) {
      _currentSyncStatus = WalletSyncStatus.syncing;
      _currentNodeStatus = NodeConnectionStatus.connected;
    } else {
      _currentSyncStatus = WalletSyncStatus.synced;
      if (wallet.isConnected) {
        _currentNodeStatus = NodeConnectionStatus.connected;
      } else {
        _currentNodeStatus = NodeConnectionStatus.disconnected;
        _currentSyncStatus = WalletSyncStatus.unableToSync;
      }
    }

    eventBus = widget.eventBus != null
        ? widget.eventBus!
        : GlobalEventBus.instance;

    _syncStatusSubscription = eventBus
        .on<WalletSyncStatusChangedEvent>()
        .listen((event) async {
          if (event.walletId == widget.walletId) {
            setState(() {
              _currentSyncStatus = event.newStatus;
            });
          }
        });

    _nodeStatusSubscription = eventBus
        .on<NodeConnectionStatusChangedEvent>()
        .listen((event) async {
          if (event.walletId == widget.walletId) {
            setState(() {
              _currentNodeStatus = event.newStatus;
            });
          }
        });

    super.initState();
  }

  @override
  void dispose() {
    _nodeStatusSubscription.cancel();
    _syncStatusSubscription.cancel();
    super.dispose();
  }

  Future<bool> _onWillPop() async {
    _logout();

    return true;
  }

  void _logout() async {
    // if (_shouldDisableAutoSyncOnLogOut) {
    //   // disable auto sync if it was enabled only when loading wallet
    ref.read(pWallets).getWallet(walletId).shouldAutoSync = false;
    // }

    ref.read(currentWalletIdProvider.notifier).state = null;
    ref.read(transactionFilterProvider.notifier).state = null;
    if (ref.read(prefsChangeNotifierProvider).isAutoBackupEnabled &&
        ref.read(prefsChangeNotifierProvider).backupFrequencyType ==
            BackupFrequencyType.afterClosingAWallet) {
      unawaited(ref.read(autoSWBServiceProvider).doBackup());
    }

    // Close the wallet according to syncing preferences.
    switch (ref.read(prefsChangeNotifierProvider).syncType) {
      case SyncingType.currentWalletOnly:
        // Close the wallet.
        unawaited(ref.watch(pWallets).getWallet(walletId).exit());
      // unawaited so we don't lag the UI.
      case SyncingType.selectedWalletsAtStartup:
        // Close if this wallet is not in the list to be synced.
        if (!ref
            .read(prefsChangeNotifierProvider)
            .walletIdsSyncOnStartup
            .contains(widget.walletId)) {
          unawaited(ref.watch(pWallets).getWallet(walletId).exit());
          // unawaited so we don't lag the UI.
        }
      case SyncingType.allWalletsOnStartup:
        // Do nothing.
        break;
    }
  }

  Widget _buildNetworkIcon(WalletSyncStatus status) {
    switch (status) {
      case WalletSyncStatus.unableToSync:
        return SvgPicture.asset(
          Assets.svg.radioProblem,
          color: Theme.of(context).extension<StackColors>()!.accentColorRed,
          width: 20,
          height: 20,
        );
      case WalletSyncStatus.synced:
        return SvgPicture.asset(
          Assets.svg.radio,
          color: Theme.of(context).extension<StackColors>()!.accentColorGreen,
          width: 20,
          height: 20,
        );
      case WalletSyncStatus.syncing:
        return SvgPicture.asset(
          Assets.svg.radioSyncing,
          color: Theme.of(context).extension<StackColors>()!.accentColorYellow,
          width: 20,
          height: 20,
        );
    }
  }

  Future<void> attemptAnonymize() async {
    bool shouldPop = false;
    unawaited(
      showDialog(
        context: context,
        builder: (context) => WillPopScope(
          child: const CustomLoadingOverlay(
            message: "Anonymizing balance",
            eventBus: null,
          ),
          onWillPop: () async => shouldPop,
        ),
      ),
    );
    final wallet = ref.read(pWallets).getWallet(walletId);

    final Amount publicBalance = wallet.info.cachedBalance.spendable;
    if (publicBalance <= Amount.zero) {
      shouldPop = true;
      if (mounted) {
        Navigator.of(context)
            .popUntil(ModalRoute.withName(WalletView.routeName));
        unawaited(
          showFloatingFlushBar(
            type: FlushBarType.info,
            message: "No funds available to privatize!",
            context: context,
          ),
        );
      }
      return;
    }

    try {
      await (wallet as PivxWallet).shieldAllTransparent();
      shouldPop = true;
      if (mounted) {
        Navigator.of(context)
            .popUntil(ModalRoute.withName(WalletView.routeName));
        unawaited(
          showFloatingFlushBar(
            type: FlushBarType.success,
            message: "Privatize transaction submitted",
            context: context,
          ),
        );
      }
    } catch (e) {
      shouldPop = true;
      if (mounted) {
        Navigator.of(context)
            .popUntil(ModalRoute.withName(WalletView.routeName));
        await showDialog<dynamic>(
          context: context,
          builder: (_) => StackOkDialog(
            title: "Privatize all failed",
            message: "Reason: $e",
          ),
        );
      }
    }
  }

